-- Original LOOX prompt starters; no external preview media or copied assets.
create table public.loox_template_catalog(
 id text primary key,title text not null,description text not null,prompt text not null check(length(prompt) between 1 and 1200),
 kind text not null check(kind in ('image','video')),category text not null,model_id text not null,settings jsonb not null default '{}',
 author text not null default 'LOOX',license text not null default 'Original LOOX prompt text. No third-party preview assets.',active boolean not null default true,created_at timestamptz not null default now());
create table public.loox_saved_templates(user_id uuid not null references auth.users(id) on delete cascade,template_id text not null references public.loox_template_catalog(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,template_id));
create table public.loox_template_launches(user_id uuid not null references auth.users(id) on delete cascade,template_id text not null references public.loox_template_catalog(id) on delete cascade,day date not null default current_date,primary key(user_id,template_id,day));
alter table public.loox_template_catalog enable row level security;
alter table public.loox_saved_templates enable row level security;
alter table public.loox_template_launches enable row level security;
revoke all on public.loox_template_catalog,public.loox_saved_templates,public.loox_template_launches from anon,authenticated;
grant select on public.loox_template_catalog to anon,authenticated;
grant select,insert,delete on public.loox_saved_templates to authenticated;
grant all on public.loox_template_catalog,public.loox_saved_templates,public.loox_template_launches to service_role;
create policy browse_original_templates on public.loox_template_catalog for select to anon,authenticated using(active);
create policy my_saved_templates on public.loox_saved_templates for select to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.loox_template_catalog t where t.id=template_id and t.active));
create policy save_original_template on public.loox_saved_templates for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.loox_template_catalog t where t.id=template_id and t.active));
create policy unsave_original_template on public.loox_saved_templates for delete to authenticated using(user_id=(select auth.uid()));
create index loox_catalog_category on public.loox_template_catalog(kind,category) where active;
create index loox_template_saves on public.loox_saved_templates(template_id);
create index loox_template_launches_template on public.loox_template_launches(template_id);

create function public.loox_launch_template(p_template text) returns void language plpgsql security invoker set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Sign in to save template usage';end if;
 if not exists(select 1 from public.loox_template_catalog where id=p_template and active) then raise exception 'Template unavailable';end if;
end $$;
-- Usage is backend only; browsing or selecting a template never reserves AI credits.
revoke all on function public.loox_launch_template(text) from public,anon,authenticated;
grant execute on function public.loox_launch_template(text) to service_role;
-- User usage records are bounded by one template launch per account/day.
grant select,insert on public.loox_template_launches to authenticated;
create policy own_template_launches on public.loox_template_launches for select to authenticated using(user_id=(select auth.uid()));
create policy launch_active_template on public.loox_template_launches for insert to authenticated with check(user_id=(select auth.uid()) and day=current_date and exists(select 1 from public.loox_template_catalog t where t.id=template_id and t.active));
grant execute on function public.loox_launch_template(text) to authenticated;
